package dev.folio;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api") @CrossOrigin(origins="*") public class LibraryController {
private final BookRepository books;private final LoanRepository loans;public LibraryController(BookRepository b,LoanRepository l){books=b;loans=l;}
@GetMapping("/books") public List<Book> books(@RequestParam(required=false)String q){return q==null||q.isBlank()?books.findAll():books.findByTitleContainingIgnoreCaseOrAuthorContainingIgnoreCase(q,q);}
@GetMapping("/loans/{studentId}") public Map<String,List<Loan>> loans(@PathVariable String studentId){return Map.of("active",loans.findByStudentIdAndReturnedOnIsNull(studentId),"history",loans.findByStudentIdAndReturnedOnIsNotNullOrderByReturnedOnDesc(studentId));}
@PostMapping("/loans") public Loan borrow(@RequestBody BorrowRequest r){Book b=books.findById(r.bookId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!b.isAvailable())throw new ResponseStatusException(HttpStatus.CONFLICT,"Already on loan");if(loans.findByStudentIdAndReturnedOnIsNull(r.studentId()).size()>=4)throw new ResponseStatusException(HttpStatus.CONFLICT,"Borrowing limit reached");b.setAvailable(false);books.save(b);return loans.save(new Loan(b.getId(),r.studentId(),LocalDate.now(),LocalDate.now().plusDays(14)));}
@PostMapping("/loans/{id}/return") public Loan giveBack(@PathVariable Long id,@RequestBody StudentRequest r){Loan l=loans.findByIdAndStudentIdAndReturnedOnIsNull(id,r.studentId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));l.setReturnedOn(LocalDate.now());books.findById(l.getBookId()).ifPresent(b->{b.setAvailable(true);books.save(b);});return loans.save(l);}
@PostMapping("/requests") public Map<String,String> request(@RequestBody BookRequest r){if(r.title()==null||r.title().isBlank()||r.author()==null||r.author().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Title and author required");return Map.of("status","received","message","Request received for librarian review.");}
public record BorrowRequest(Long bookId,String studentId){} public record StudentRequest(String studentId){} public record BookRequest(String title,String author,String reason){}
}